head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.clickBzProcsNo = "";
scwin.vScrenID = "ULDSTF05955.xml";
scwin.vStep_2 = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 조회날짜 세팅
scwin.fn_setDate = function() {
    var today = $c.ut.cGetToday("yyyymmdd");
    var fromYear = 2005;
    var toYear = today.substring(0, 4);
    var curQ = Math.ceil(today.substring(4, 6) / 3);
    if (curQ == 1) {
        toYear = toYear - 1;
        $c.stf.setObjectValue(cmb_QuarterTp, 4);
    } else {
        $c.stf.setObjectValue(cmb_QuarterTp, curQ - 1);
    }
    var strCbd = "";
    for (i = toYear; i >= fromYear; i--) {
        strCbd = strCbd + (strCbd == "" ? "" : ",") + i + "년^" + i;
    }
    cmb_YearTp.CBData = strCbd;
    cmb_YearTp.setSelectedIndex(0);
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=ELW_ULY_SELCT_YEARQT_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.list.elw.isu.yyyyquarter.select";
    dts_YearQuarter.DataID = encodeURI(url);
    dts_YearQuarter.Reset();
};


// 기초자산명 display
scwin.fn_SetValues = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.setObjectValue(txb_ISUR_CD, dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"));
        $c.stf.setObjectValue(txb_COM_NM, dts_List.getCellData(dts_List.getRowPosition(), "ISU_ABBRV"));
        $c.stf.setObjectValue(txb_WRNT_ULY_NM, dts_List.getCellData(dts_List.getRowPosition(), "WRNT_ULY_NM"));
        $c.stf.setObjectValue(txb_WRNT_ULY_ENG_NM, dts_List.getCellData(dts_List.getRowPosition(), "WRNT_ULY_ENG_NM"));
    }
};



// 조회
scwin.fn_list_sync = function() {
    var url = "/ElwListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listElwKospi200UlyInfo&inputMessageId=ELW_KOSPI200_ULY_SELCT_INOUT";
    url += "&BAS_DATE=" + $c.stf.getObjectValue(edt_BDate);
    url += "&START_DATE=" + $c.stf.getObjectValue(edt_SDate);
    url += "&END_DATE=" + $c.stf.getObjectValue(edt_EDate);
    url += "&REG_EMP_NO=" + js_emp_no;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};


// 종목선정후 조회
scwin.fn_list_sync_final = function() {
    var url = "/ElwListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listElwKospi200UlyFinalInfo&inputMessageId=ELW_KOSPI200_ULY_SELCT_INOUT";
    url += "&BAS_DATE=" + $c.stf.getObjectValue(edt_BDate);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



// 하단 종목 체크수 표시
scwin.fn_NotiCount = function() {
    var vCnt = 0;
    if (dts_List.getTotalRow() > 0) {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            if (dts_List.getCellData(i, "CHK") == "T") {
                vCnt = vCnt + 1;
            }
        }
    }
    $c.stf.setObjectValue(txb_NotiCount, "현재 " + vCnt + "종목이 선택되어 있습니다.");
};


// 기초자산명 lengths 체크
scwin.fn_WrntUlyCheck = function() {
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_NM, "한글기초자산명")) {
        txb_WRNT_ULY_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_NM, 8, "한글기초자산명")) {
        txb_WRNT_ULY_NM.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_ENG_NM, "영문기초자산명")) {
        txb_WRNT_ULY_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_ENG_NM, 8, "영문기초자산명")) {
        txb_WRNT_ULY_ENG_NM.focus();
        return false;
    }
    return true;
};


// 기초자산명 저장
scwin.fn_WrntUlySave = function() {
    if (scwin.fn_WrntUlyCheck()) {
        dts_WrntUly.removeAll();
        //dts_WrntUly.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_WrntUly.insertRow();
        dts_WrntUly.setCellData(1, "WRNT_ULY_NM", $c.stf.getObjectValue(txb_WRNT_ULY_NM));
        dts_WrntUly.setCellData(1, "WRNT_ULY_ENG_NM", $c.stf.getObjectValue(txb_WRNT_ULY_ENG_NM));
        dts_WrntUly.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
        trs_WrntSave.Action = "/ElwListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=saveElwWrntUly";
        trs_WrntSave.KeyName = "toinb_dataid4";
        trs_WrntSave.KeyValue = "JSP(I:pInput=dts_WrntUly)";
        trs_WrntSave.Post();
    }
};



// 종목선정(50종목체크)
scwin.IsuCountCheck = function() {
    var vCnt = 0;
    if (dts_List.getTotalRow() > 0) {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            if (dts_List.getCellData(i, "CHK") == "T") {
                vCnt = vCnt + 1;
            }
        }
    }
    if (vCnt != 50) {
        $c.win.alert("50종목만 선택해 주세요.");
        return false;
    }
    return true;
};


//  종목선정 저장
scwin.fn_IsuSelctSave = function() {
    if (scwin.IsuCountCheck()) {
        trs_IsuSelctSave.Action = "/ElwListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=saveElwIsuSelct";
        trs_IsuSelctSave.KeyName = "toinb_dataid4";
        trs_IsuSelctSave.KeyValue = "JSP(I:pInput=dts_List)";
        trs_IsuSelctSave.Post();
    }
};



// 최종 저장
scwin.fn_finalSave = function() {
    if (scwin.IsuCountCheck()) {
        dts_final.removeAll();
        //dts_final.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        if (dts_List.getTotalRow() > 0) {
            for (var i = 1; i <= dts_List.getTotalRow(); i++) {
                if (dts_List.getCellData(i, "CHK") == "T") {
                    dts_final.insertRow();
                    dts_final.setCellData(dts_final.getRowPosition(), "BAS_YYMM", dts_List.getCellData(i, "BAS_YYMM"));
                    dts_final.setCellData(dts_final.getRowPosition(), "ISU_CD", dts_List.getCellData(i, "ISU_CD"));
                    dts_final.setCellData(dts_final.getRowPosition(), "ISU_KOR_ABBRV", dts_List.getCellData(i, "ISU_ABBRV"));
                    dts_final.setCellData(dts_final.getRowPosition(), "RANK", dts_final.getRowPosition());
                    dts_final.setCellData(dts_final.getRowPosition(), "DYAVG_TRDVAL", dts_List.getCellData(i, "DYAVG_TRDVAL"));
                    dts_final.setCellData(dts_final.getRowPosition(), "MKTCAP", dts_List.getCellData(i, "MKTCAP"));
                }
            }
        }
        trs_IsuSelFinalSave.Action = "/ElwListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=saveElwIsuSelctFinal";
        trs_IsuSelFinalSave.KeyName = "toinb_dataid4";
        trs_IsuSelFinalSave.KeyValue = "JSP(I:pInput=dts_final)";
        trs_IsuSelFinalSave.Post();
    }
};



// 엑셀 저장
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, "발행가능KOSPI200 기초자산 선정", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_setYearQuarter = function() {
    var baseYq = "" + $c.stf.getObjectValue(cmb_YearTp) + $c.stf.getObjectValue(cmb_QuarterTp);
    $c.stf.setObjectValue(edt_SDate, "");
    $c.stf.setObjectValue(edt_EDate, "");
    $c.stf.setObjectValue(edt_BDate, "");
    for (i = 1; i <= dts_YearQuarter.getTotalRow(); i++) {
        if (dts_YearQuarter.getCellData(i, "YYYYQ") == baseYq) {
            $c.stf.setObjectValue(edt_SDate, dts_YearQuarter.getCellData(i, "FROM_DD"));
            $c.stf.setObjectValue(edt_EDate, dts_YearQuarter.getCellData(i, "VALUE"));
            $c.stf.setObjectValue(edt_BDate, dts_YearQuarter.getCellData(i, "VALUE"));
            break;
        }
    }
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
        scwin.vStep_2 = "N";
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
    scwin.fn_NotiCount();
    scwin.fn_SetValues();
};
scwin.dts_YearQuarter_OnLoadCompleted = function(rowcount) {
    scwin.fn_setYearQuarter();
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_BDate_onclick = function() {
    popUpCalendar2(edt_BDate);
};
scwin.cmb_YearTp_OnSelChange = function() {
    scwin.fn_setYearQuarter();
};
scwin.cmb_QuarterTp_OnSelChange = function() {
    scwin.fn_setYearQuarter();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_wrnt_uly_save_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        var rtn = confirm(dts_List.getCellData(dts_List.getRowPosition(), "ISU_ABBRV") + ' 종목에 대한 기초자산명을 저장 하시겠습니까?');
        if (rtn == 1) {
            // [확인] 버튼이 눌려졌을 경우	
            scwin.fn_WrntUlySave();
        }
    }
};
scwin.btn_FinalSave_onclick = function() {
    var rtn = confirm('(3단계) 최종 저장 하시겠습니까?');
    if (rtn == 1) {
        // [확인] 버튼이 눌려졌을 경우		
        if (scwin.vStep_2 == "N") {
            $c.win.alert("(2단계) 종목 선정이 저장되지 않았습니다. 종목 선정부터 진행해주세요.");
            return false;
        }
        scwin.fn_finalSave();
    }
};
scwin.grd_List_OnClick = function(row, colid) {
    if (colid == "CHK") {
        //if(dts_List.NameString(row, "CHK") == "T" && dts_List.NameString(row, "COND_SATISFACT_YN") == "N"){
        //	alert("해당종목은 1차선정시 로직 1~5번 미충족으로 제외된 종목으로 선정불가 종목입니다.");		
        //	dts_List.NameValue(row, "CHK") = "F";
        //}
        scwin.fn_NotiCount();
    }
    scwin.fn_SetValues();
};
scwin.btn_IsuSelect_onclick = function() {
    var rtn = confirm('(2단계) 종목선정을 저장하시겠습니까?');
    if (rtn == 1) {
        // [확인] 버튼이 눌려졌을 경우			
        scwin.fn_IsuSelctSave();
    }
};
scwin.trs_WrntSave_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    if (scwin.vStep_2 == "N") {
        scwin.fn_list_sync();
    } else {
        scwin.fn_list_sync_final();
    }
};
scwin.trs_WrntSave_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
};
scwin.trs_IsuSelctSave_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.vStep_2 = "Y";
    scwin.fn_list_sync_final();
};
scwin.trs_IsuSelctSave_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    scwin.vStep_2 = "N";
};
scwin.trs_IsuSelFinalSave_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    scwin.vStep_2 = "N";
};
scwin.trs_IsuSelFinalSave_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.vStep_2 = "Y";
    scwin.fn_list_sync_final();
};
scwin.gform_onload = function() {
    scwin.fn_setDate();
    //Combo_CBDataSetPeriod(cmb_PeriodTp);

};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
